function samples(o,t){const a=[];for(let x=0;x<=Math.ceil(o.w);x++)for(let z=0;z<=Math.ceil(o.d);z++){const px=o.x-o.w/2+o.w*x/Math.ceil(o.w),pz=o.z-o.d/2+o.d*z/Math.ceil(o.d);a.push({x:px,z:pz,...t.sample(px,pz)});}return a;}
