 items.push(make('incoming-logs','WW-002',-4+ox,0+oz,'Stage cut timber before processing',['haul'],'cart'),make('habitat-deadwood','WW-018',-24+ox,11+oz,'Retain deadwood habitat beyond the working yard',['habitat']));
 for(const o of items){o.orientation=o.id==='tool-shelter'||o.id==='tool-wall'?Math.PI/2:o.id.startsWith('seasoning-')?-Math.PI/2:0;if(o.orientation){const w=o.w;o.w=o.d;o.d=w;}o.localDimensions={...dimensions[o.model]};}
