 const edge={x:21.6506350946,z:37.5};let clear=true;for(let i=0;i<=20;i++)for(const dx of [-1.5,0,1.5]){const p=t.sample(edge.x+(arrival.x-edge.x)*i/20+dx,edge.z+(arrival.z-edge.z)*i/20);if(p.bank<5||p.grade>.12)clear=false;}if(!clear)continue;
